  <div class="zoom-controls" role="group" aria-label="Camera zoom"><button class="icon-button" data-zoom="0.8" aria-label="Zoom out">−</button><output id="zoom-label" aria-live="polite">100%</output><button class="icon-button" data-zoom="1.25" aria-label="Zoom in">+</button></div>
